return-response.set-body:
@{
          var granted = context.Variables.GetValueOrDefault("aipGranted", "");
          var body = new JObject();
          body["team"] = context.Variables.GetValueOrDefault("aipTeam", "");
          body["credentialType"] = context.Variables.GetValueOrDefault("aipTier", "oauth");
          body["clientId"] = context.Variables.GetValueOrDefault("aipClientId", "");
          body["accessWindow"] = context.Variables.GetValueOrDefault("aipWindow", "");
          body["allowedDeployments"] = JArray.FromObject(granted.Split(',').Where(slug => slug != ""));
          return body.ToString();
        }
